def _finalize_new_project(*, name: str, archetype: str, duration: int,
                          fte_cost_monthly: float,
                          direct_cost: np.ndarray, fte_count: np.ndarray,
                          business_value: np.ndarray,
                          existing: list[Project]) -> None:
    """Assign the next sequential id, persist the project, refresh caches."""
    existing_ids = {p.project_id for p in existing}
    n = 1
    while f"P-{n:04d}" in existing_ids:
        n += 1
    new_id = f"P-{n:04d}"

    new_project = Project(
        project_id=new_id,
        name=f"{name.strip()} ({new_id})",
        archetype=archetype,
        duration_months=int(duration),
        fte_cost_monthly=float(fte_cost_monthly),
        direct_cost=direct_cost,
        fte_count=fte_count,
        business_value=business_value,
    )
    append_project(new_project)
    st.cache_data.clear()
    st.success(
        f"Added '{name.strip()}' as {new_id}. "
        f"Total NP: {fmt_money(new_project.total_net_profit)} • "
        f"Break-even: {new_project.break_even_month or 'never'} mo."
    )
    st.info("Switch to the Ranking tab — the portfolio has been re-prioritised.")


def _render_detailed_add(projects: list[Project]) -> None:
    """Detailed mode: the user has a full business case with monthly numbers."""
    st.markdown(
        "**Detailed mode** — enter every KPI per month. The system computes "
        "monthly cost, monthly net profit, and the totals automatically."
    )

    name_d = st.text_input("Project name", key="detailed_name")
    c1, c2, c3 = st.columns(3)
    with c1:
        archetype_d = st.selectbox(
            "Archetype (for tagging only)",
            options=[a.name for a in ARCHETYPES] + ["Custom"],
            key="detailed_archetype",
        )
    with c2:
        duration_d = int(st.number_input(
            "Duration (months)", min_value=1, max_value=72, value=12, step=1,
            key="detailed_duration",
        ))
    with c3:
        fte_cost_monthly_d = float(st.number_input(
            f"FTE cost / month ({CURRENCY})", min_value=0.0,
            value=13_000.0, step=500.0, key="detailed_fte_cost_monthly",
            help="Loaded cost per FTE per month (same across the project).",
        ))

    # Manage the editable table in session_state so edits persist across reruns,
    # rebuilding only when duration changes.
    table_key = "detailed_table"
    if (table_key not in st.session_state
            or len(st.session_state[table_key]) != duration_d):
        st.session_state[table_key] = pd.DataFrame({
            "month": np.arange(1, duration_d + 1),
            "business_value": [0.0] * duration_d,
            "direct_cost": [0.0] * duration_d,
            "fte_count": [0.0] * duration_d,
        })

    st.markdown("##### Monthly inputs")
    edited = st.data_editor(
        st.session_state[table_key],
        column_config={
            "month": st.column_config.NumberColumn("Month", format="%d", width="small"),
            "business_value": st.column_config.NumberColumn(
                f"Business Value ({CURRENCY})",
                min_value=0.0, step=10_000.0, format="%.0f",
                help="Revenue, savings, or reduced risk cost generated this month.",
            ),
            "direct_cost": st.column_config.NumberColumn(
                f"Direct Cost ({CURRENCY})",
                min_value=0.0, step=5_000.0, format="%.0f",
                help="Spend this month: consultants, licenses, infrastructure.",
            ),
            "fte_count": st.column_config.NumberColumn(
                "FTE Count",
                min_value=0.0, step=0.5, format="%.1f",
                help="Full-time-equivalent people on the project this month.",
            ),
        },
        disabled=["month"],
        num_rows="fixed",
        hide_index=True,
        use_container_width=True,
        key="detailed_editor",
    )
    st.session_state[table_key] = edited

    # Live preview of derived KPIs
    bv = edited["business_value"].to_numpy(dtype=float)
    dc = edited["direct_cost"].to_numpy(dtype=float)
    fte = edited["fte_count"].to_numpy(dtype=float)
    monthly_cost = dc + fte * fte_cost_monthly_d
    monthly_np = bv - monthly_cost
    cum = np.cumsum(monthly_np)
    pos = np.where(cum >= 0)[0]
    break_even = int(pos[0] + 1) if pos.size > 0 else None

    st.markdown("##### Live preview")
    m1, m2, m3, m4 = st.columns(4)
    m1.metric("Total business value", fmt_money(bv.sum()))
    m2.metric("Total cost", fmt_money(monthly_cost.sum()))
    m3.metric("Total net profit", fmt_money(monthly_np.sum()))
    m4.metric("Break-even month", str(break_even) if break_even else "never")

    preview_df = pd.DataFrame({
        "month": np.arange(1, duration_d + 1),
        "monthly_net_profit": monthly_np,
        "cumulative_net_profit": cum,
    })
    fig = px.line(
        preview_df, x="month", y="cumulative_net_profit", markers=True,
        labels={"month": "Month", "cumulative_net_profit": f"Cumulative NP ({CURRENCY})"},
    )
    fig.add_hline(y=0, line_dash="dash", line_color="gray", opacity=0.6)
    fig.update_layout(height=300, margin=dict(t=20, b=20))
    st.plotly_chart(fig, use_container_width=True)

    if st.button("Add project", type="primary", key="detailed_submit"):
        if not name_d.strip():
            st.error("Please provide a project name.")
        elif bv.sum() == 0 and dc.sum() == 0 and fte.sum() == 0:
            st.error("All monthly inputs are zero — please fill in at least some values.")
        else:
            _finalize_new_project(
                name=name_d, archetype=archetype_d, duration=duration_d,
                fte_cost_monthly=fte_cost_monthly_d,
                direct_cost=dc, fte_count=fte, business_value=bv,
                existing=projects,
            )
            # Reset the table after a successful submit
            del st.session_state[table_key]


def _render_highlevel_add(projects: list[Project]) -> None:
    """High-level mode: only totals + archetype + duration."""
    st.markdown(
        "**High-level mode** — enter totals and ranges. The system spreads them "
        "across the months using a value-curve shape."
    )

    archetype_names = [a.name for a in ARCHETYPES]
    archetype_h = st.selectbox(
        "Archetype",
        options=archetype_names + ["Custom"],
        key="highlevel_archetype",
        help="Drives the default value-curve shape and pre-fills sensible numbers.",
    )
    archetype_obj = next((a for a in ARCHETYPES if a.name == archetype_h), None)

    # Defaults: midpoint of the archetype's ranges, or generic defaults for Custom
    if archetype_obj is not None:
        d_default = sum(archetype_obj.duration_range) // 2
        cost_share_default = sum(archetype_obj.cost_phase_share_range) / 2
        fte_cost_default = sum(archetype_obj.fte_cost_phase_range) // 2
        fte_gain_default = sum(archetype_obj.fte_gain_phase_range) // 2
        dc_cost_default = sum(archetype_obj.direct_cost_phase_range) / 2
        dc_gain_default = sum(archetype_obj.direct_gain_phase_range) / 2
        fte_monthly_default = sum(archetype_obj.fte_cost_monthly_range) / 2
        total_value_default = sum(archetype_obj.total_value_range) / 2
        archetype_shape_name = next(
            (k for k, v in VALUE_SHAPES.items() if v is archetype_obj.value_shape),
            "Linear ramp",
        )
    else:
        d_default, cost_share_default = 12, 0.5
        fte_cost_default, fte_gain_default = 4, 2
        dc_cost_default, dc_gain_default = 50_000.0, 10_000.0
        fte_monthly_default, total_value_default = 13_000.0, 2_000_000.0
        archetype_shape_name = "Linear ramp"

    name_h = st.text_input("Project name", key="highlevel_name")

    c1, c2 = st.columns(2)
    with c1:
        duration_h = int(st.number_input(
            "Duration (months)", min_value=1, max_value=72,
            value=int(d_default), step=1, key="highlevel_duration",
        ))
        cost_share = st.slider(
            "Share of duration in cost phase", 0.0, 1.0,
            float(cost_share_default), 0.05, key="highlevel_cost_share",
            help="Fraction of months at the start with no business value yet.",
        )
        total_value = float(st.number_input(
            f"Total business value over gain phase ({CURRENCY})",
            min_value=0.0, value=float(total_value_default), step=100_000.0,
            key="highlevel_total_value",
        ))
    with c2:
        fte_cost_n = int(st.number_input(
            "FTE count during cost phase", min_value=0, max_value=100,
            value=int(fte_cost_default), step=1, key="highlevel_fte_cost",
        ))
        fte_gain_n = int(st.number_input(
            "FTE count during gain phase", min_value=0, max_value=100,
            value=int(fte_gain_default), step=1, key="highlevel_fte_gain",
        ))
        fte_cost_monthly_h = float(st.number_input(
            f"Avg FTE cost per month ({CURRENCY} / FTE / month)",
            min_value=0.0, value=float(fte_monthly_default), step=500.0,
            key="highlevel_fte_cost_monthly",
        ))
        dc_cost_phase = float(st.number_input(
            f"Avg direct cost / month — cost phase ({CURRENCY})",
            min_value=0.0, value=float(dc_cost_default), step=5_000.0,
            key="highlevel_dc_cost",
        ))
        dc_gain_phase = float(st.number_input(
            f"Avg direct cost / month — gain phase ({CURRENCY})",
            min_value=0.0, value=float(dc_gain_default), step=1_000.0,
            key="highlevel_dc_gain",
        ))

    st.markdown("##### Value distribution over the gain phase")
    auto_estimate = st.toggle(
        "Auto-estimate distribution from archetype",
        value=True,
        key="highlevel_auto_estimate",
        help=(
            "ON: use the typical value-curve shape for the selected archetype. "
            "OFF: pick the shape yourself."
        ),
    )

    if auto_estimate:
        if archetype_obj is not None:
            shape_name_h = archetype_shape_name
            st.caption(
                f"Using **{shape_name_h}** — typical for *{archetype_h}*."
            )
        else:
            shape_name_h = "Linear ramp"
            st.caption(
                "Custom archetype has no archetype-specific shape; falling back to **Linear ramp**."
            )
    else:
        shape_name_h = st.selectbox(
            "Value-curve shape",
            options=list(VALUE_SHAPES.keys()),
            index=list(VALUE_SHAPES.keys()).index(archetype_shape_name),
            key="highlevel_shape",
        )

    if st.button("Add project", type="primary", key="highlevel_submit"):
        if not name_h.strip():
            st.error("Please provide a project name.")
        else:
            n = duration_h
            cost_months = max(1, int(round(n * cost_share)))
            cost_months = min(cost_months, n - 1) if n > 1 else cost_months
            gain_months = n - cost_months

            direct = np.empty(n)
            direct[:cost_months] = dc_cost_phase
            if gain_months > 0:
                direct[cost_months:] = dc_gain_phase

            fte = np.empty(n)
            fte[:cost_months] = fte_cost_n
            if gain_months > 0:
                fte[cost_months:] = fte_gain_n

            value = np.zeros(n)
            if gain_months > 0:
                rng = np.random.default_rng()
                shape = VALUE_SHAPES[shape_name_h](gain_months, rng)
                value[cost_months:] = shape * total_value

            _finalize_new_project(
                name=name_h,
                archetype=archetype_h if archetype_obj else "Custom",
                duration=n,
                fte_cost_monthly=fte_cost_monthly_h,
                direct_cost=direct, fte_count=fte, business_value=value,
                existing=projects,
            )


